	t = int(input())
	for _ in range(t):
		n = int(input())
		edges = [[int(a) for a in input().split()] for _ in range(n - 1)]
		aa = [0] + [int(a) for a in input().split()]
		res = solve(n, edges, aa)
		print(' '.join(map(str, res)))
INF = 10000000000000000

def solve(n, edges, aa):
	adj = [[] for _ in range(n + 1)]
	for (u, v) in edges:
		adj[u].append(v)
		adj[v].append(u)
	parent = [0] * (n + 1)
	dl = []
	q = deque([1])
	while q:
		v = q.popleft()
		for w in adj[v]:
			if w != parent[v]:
				dl.append(w)
				parent[w] = v
				q.append(w)
	dl.reverse()
	res = [INF] * (n + 1)
	values = [RedBlackTree() for _ in range(n + 1)]
	for (i, a) in enumerate(aa):
		values[i].insert(a)
	for u in dl:
		res[parent[u]] = min(res[parent[u]], res[u])
		if len(values[u]) > len(values[parent[u]]):
			(values[u], values[parent[u]]) = (values[parent[u]], values[u])
		for v in values[u]:
			values[parent[u]].insert(v)
			vn = values[parent[u]].find(v)
			pn = vn.prev()
			if pn:
				res[parent[u]] = min(res[parent[u]], pn.key ^ v)
			nn = vn.next()
			if nn:
				res[parent[u]] = min(res[parent[u]], nn.key ^ v)
	return [-1 if r == INF else r for r in res[1:]]
